-- m20220101_000005_governance: frozen on 11 November 2026 from the statements its sea-orm-migration `up` ran on PostgreSQL 18,
-- in order. Never edit it: `_sqlx_migrations` holds its checksum. A change is a new migration.
--
-- What the Rust migration said of itself:
--
-- Migration: the PPM Phase-A **governance core** (spec/15-roadmap
-- PPM-1/3/10/12) — `proposals` (work intake), `gate_reviews` +
-- a `plans.stage` column (phase gates), `risks`, and
-- `budget_lines`. All are operational sub-resources: never matcher
-- signals, always audited. Money is stored as integer **minor
-- units** (`*_minor`) plus an ISO-4217 currency code — exact, no
-- floats, no decimal dependency.

CREATE TABLE IF NOT EXISTS "proposals" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "title" varchar NOT NULL, "summary" text NULL, "kind_target" varchar NOT NULL, "sponsor_ref" varchar NULL, "strategic_rationale" text NULL, "requested_minor" bigint NULL, "currency" varchar NULL, "status" varchar NOT NULL, "promoted_plan_pid" uuid NULL, "deleted_at" timestamp with time zone NULL );

CREATE TABLE IF NOT EXISTS "gate_reviews" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "plan_pid" uuid NOT NULL, "gate" varchar NOT NULL, "decision" varchar NOT NULL, "conditions" text NULL, "approver_ref" varchar NULL, "decided_at" timestamp with time zone NOT NULL );

CREATE TABLE IF NOT EXISTS "risks" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "plan_pid" uuid NOT NULL, "title" varchar NOT NULL, "description" text NULL, "probability" integer NOT NULL, "impact" integer NOT NULL, "status" varchar NOT NULL, "owner_ref" varchar NULL, "mitigation" text NULL, "review_date" date NULL, "escalated_at" timestamp with time zone NULL, "deleted_at" timestamp with time zone NULL );

CREATE TABLE IF NOT EXISTS "budget_lines" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "plan_pid" uuid NOT NULL, "category" varchar NOT NULL, "description" varchar NOT NULL, "currency" varchar NOT NULL, "planned_minor" bigint NOT NULL, "actual_minor" bigint NOT NULL, "period_start" date NULL, "period_end" date NULL, "deleted_at" timestamp with time zone NULL );

ALTER TABLE plans ADD COLUMN stage VARCHAR NULL;

CREATE INDEX IF NOT EXISTS proposals_status ON proposals (status) WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS gate_reviews_item ON gate_reviews (plan_pid);

CREATE INDEX IF NOT EXISTS risks_item ON risks (plan_pid);

CREATE INDEX IF NOT EXISTS budget_lines_item ON budget_lines (plan_pid);
